#include <gio/gio.h>
#include <stdio.h>
int main(void){GError*error=NULL;const char*runtime=g_getenv("XDG_RUNTIME_DIR");if(!runtime)return 1;gchar*address=g_strdup_printf("unix:path=%s/maliit-server/dbus-socket",runtime);GDBusConnection*connection=g_dbus_connection_new_for_address_sync(address,G_DBUS_CONNECTION_FLAGS_AUTHENTICATION_CLIENT,NULL,NULL,&error);g_free(address);if(!connection){fprintf(stderr,"Maliit connection: %s\n",error?error->message:"unknown");return 2;}GVariant*reply=g_dbus_connection_call_sync(connection,NULL,"/com/meego/inputmethod/uiserver1","org.freedesktop.DBus.Introspectable","Introspect",NULL,G_VARIANT_TYPE("(s)"),G_DBUS_CALL_FLAGS_NONE,2000,NULL,&error);if(!reply){fprintf(stderr,"Maliit introspection: %s\n",error?error->message:"unknown");return 3;}const gchar*xml;g_variant_get(reply,"(&s)",&xml);puts(xml);g_variant_unref(reply);g_dbus_connection_close_sync(connection,NULL,NULL);g_object_unref(connection);return 0;}
